{
  "core_issue": "評估「120萬元投資、年省45萬元」的自動化設備專案是否如使用者所言「安全」，需釐清回收期計算是否忽略關鍵變數（維護費、壽命、折舊、風險）。",
  "known_facts": [
    {
      "text": "設備總價為 120 萬元（含安裝）。",
      "source": "Q3, D-FIN"
    },
    {
      "text": "預估每年節省人工成本為 45 萬元。",
      "source": "Q4, D-FIN"
    },
    {
      "text": "每年維護費用未列入成本估算。",
      "source": "D-FIN"
    },
    {
      "text": "設備壽命未提供。",
      "source": "D-FIN"
    }
  ],
  "unknowns": [
    {
      "what": "年度維護與營運成本 (OPEX)",
      "why_it_matters": "若維護費高於節省額，投資將虧損；此為計算真實淨現金流的關鍵變數。",
      "how_to_get": "向設備供應商索取標準維護合約報價或歷史同型設備維護數據。"
    },
    {
      "what": "設備經濟壽命與殘值",
      "why_it_matters": "決定折舊攤提與長期投資報酬率 (ROI)；若壽命短於回收期，投資無意義。",
      "how_to_get": "查閱設備技術規格書或詢問供應商保固與預期使用年限。"
    },
    {
      "what": "資金成本 (Discount Rate) 與稅務影響",
      "why_it_matters": "使用者僅計算靜態回收期，未考慮貨幣時間價值與稅後現金流，可能高估安全性。",
      "how_to_get": "諮詢財務部門獲取公司加權平均資本成本 (WACC) 及稅務折舊政策。"
    },
    {
      "what": "實施風險與潛在停機損失",
      "why_it_matters": "自動化設備可能導致生產中斷或需要額外培訓，這些隱形成本未計入。",
      "how_to_get": "進行專案管理風險評估與營運部門訪談。"
    }
  ],
  "hard_constraints": [
    {
      "text": "預算上限為 120 萬元（基於使用者陳述與文件一致）。",
      "source": "Q1, Q3"
    }
  ],
  "conflicts": [
    {
      "text": "使用者聲稱「回收期不到兩年」，但根據已知數據（120/45 = 2.67年），靜態回收期實際超過兩年。此為計算邏輯或數據定義上的矛盾。",
      "sources": [
        "Q3",
        "Q4",
        "user_turn_1"
      ]
    }
  ],
  "calculations": [
    {
      "name": "靜態回收期 (Simple Payback Period)",
      "formula": "Investment / Annual_Savings",
      "inputs": {
        "Investment": "Q3",
        "Annual_Savings": "Q4"
      },
      "unit": "年",
      "meaning": "在不考慮維護費、折舊與時間價值下，收回初始投資所需的時間。"
    },
    {
      "name": "淨年節省額 (Net Annual Savings)",
      "formula": "Annual_Savings - Annual_Maintenance_Cost",
      "inputs": {
        "Annual_Savings": "Q4",
        "Annual_Maintenance_Cost": "unknown"
      },
      "unit": "萬元/年",
      "meaning": "扣除維護成本後的真實年度現金流入。若此值為負，則投資不可行。"
