      ],
      "cons": [
        "需要額外時間與資源進行調查。"
      ],
      "cost_impact": "調查成本（通常遠低於 120 萬）"
    }
  ],
  "recommended_actions": [
    {
      "action": "向供應商索取年度維護費用預估與設備預期壽命數據。",
